def transform(grid):
    # Extend a repeated diagonal color pair outward, away from the denser part of the object.
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                rr, cc = r + dr, c + dc
                if not (0 <= rr < h and 0 <= cc < w) or grid[rr][cc] != color:
                    continue
                pair = frozenset(((r, c), (rr, cc)))
                if pair in seen:
                    continue
                seen.add(pair)
                # Choose the endpoint with fewer neighboring non-background pixels,
                # then continue away from the other endpoint.
                def crowd(pos):
                    pr, pc = pos
                    return sum(1 for ar in range(max(0, pr-1), min(h, pr+2))
                               for ac in range(max(0, pc-1), min(w, pc+2))
                               if (ar, ac) not in pair and grid[ar][ac] != bg)
                a, b = (r, c), (rr, cc)
                if crowd(a) <= crowd(b):
                    sr, sc = a
                    step_r, step_c = -dr, -dc
                else:
                    sr, sc = b
                    step_r, step_c = dr, dc
                sr += step_r
                sc += step_c
                while 0 <= sr < h and 0 <= sc < w:
                    if out[sr][sc] == bg:
                        out[sr][sc] = color
                    sr += step_r
                    sc += step_c
    return out
